  const gridX = (x % frameW < 2 || x % frameW > frameW - 2) ? 1 : 0;
  const gridY = (y % frameH < 2 || y % frameH > frameH - 2) ? 1 : 0;
  const frame = (gridX || gridY) ? 0.8 : 0;

  // Status bars
  const barY = y < 8 ? 1 : (y > 231 ? 1 : 0);
  const barVal = Math.sin(t * primes[Math.floor(x/48) % primes.length] * 0.5) * 0.5 + 0.5;
  const statusBar = barY ? barVal : 0;

  // Text line simulation using primes
  const lineSpacing = primes[1]; // 3
  const textLine = (y % (lineSpacing * 4) < lineSpacing) ? Math.sin(x * 0.5 + t) * 0.5 + 0.5 : 0;
  const textRegion = (x > 10 && x < 130 && y > 15 && y < 95) ? textLine * 0.4 : 0;

  // Combine
  const uiMix = Math.max(frame, statusBar, textRegion);
  v = v * (1 - uiMix) + uiMix * 0.7;

  // Neon palette
  const pal = [
    [5, 2, 30],      // deep violet-black
    [20, 0, 80],     // dark purple
    [0, 60, 180],    // blue
    [0, 200, 255],   // cyan neon
    [100, 255, 200], // mint neon
    [255, 255, 100], // yellow neon
    [255, 100, 50],  // orange neon
    [255, 0, 80],    // hot pink neon
    [180, 0, 60],    // magenta
    [5, 2, 30]       // deep violet-black
  ];

  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;

  // High contrast boost
  const contrast = 1.4;
  const lum = (0.6 + Math.abs(reaction)*0.4) * contrast;
  const neonGlow = Math.pow(Math.abs(reaction), 0.5) * 1.3;
  const edge = Math.abs(reaction) > 0.6 ? 1.4 : 1.0;
  const finalMul = lum * edge + (neonGlow - 1) * 0.3;

  // UI colors override
  const uiColor = frame ? [0, 180, 255] : (statusBar ? [255, 200, 50] : (textRegion ? [100, 255, 180] : null));

  if (uiColor) {
    const uiLum = 0.6 + Math.sin(t * 2) * 0.15;
    return [
      Math.min(255, uiColor[0] * uiLum)|0,
      Math.min(255, uiColor[1] * uiLum)|0,
      Math.min(255, uiColor[2] * uiLum)|0
    ];
  }

  return
